import math

def min_Jumps(d: float, length: float) -> int:
    if d == 0:
        return 0
    if length >= d:
        return 1
    # If length < d, check if two jumps can do it (triangle inequality)
    # Two jumps of length 'length' can reach any point within distance 2*length.
    # But if d > length, one jump is not enough.
    # For two jumps, if the distance d is exactly length, one jump is enough.
    # If d <= 2*length but not equal to length, two jumps can reach it.
    if 2 * length >= d:
        return 2
    # Otherwise, more jumps are needed.
    # The minimal number of jumps is the ceiling of d / length.
    return math.ceil(d / length)

