def anti_shuffle(s):
    def sort_word(w):
        # If the word has no letters, just return it as is
        if not any(c.isalpha() for c in w):
            return w
        # Separate trailing non-letters
        i = len(w)
        while i > 0 and not w[i-1].isalpha():
            i -= 1
        prefix = w[:i]
        suffix = w[i:]
        # Sort only the prefix letters
        sorted_prefix = ''.join(sorted(prefix))
        return sorted_prefix + suffix

    return ' '.join(sort_word(word) for word in s.split(' '))

